-- ============================================
-- LUMA — Thème 12 : LONG 2/3 x4 — Une chasse au trésor culturelle dans le musée
-- ============================================


update scenarios set content = '{"characters": {"organizer": "l''organisateur", "rival_team": "l''équipe rivale", "clue_card": "carte indice"}, "start_node": "n1", "nodes": {"n1": {"speaker": "organizer", "text": "Welcome to the Museum Treasure Hunt! Solve clues, find artifacts, and race the clock. Ready?", "text_fr": "Bienvenue à la Chasse au Trésor du Musée ! Résolvez des indices, trouvez des artefacts, et courez contre la montre. Prêt ?", "choices": [{"text": "Absolutely, let''s see this first clue!", "text_fr": "Absolument, voyons ce premier indice !", "next": "n2"}, {"text": "I''m ready, though I noticed another team is here too — is this a race?", "text_fr": "Je suis prêt, même si j''ai remarqué qu''une autre équipe est là aussi — c''est une course ?", "next": "n2b"}]}, "n1b": {"speaker": "rival_team", "text": "(Waves) Good luck! May the best treasure hunter win!", "text_fr": "(Fait signe) Bonne chance ! Que le meilleur chasseur de trésor gagne !", "choices": [{"text": "Same to you! Let''s make this fun.", "text_fr": "Pareil pour vous ! Faisons que ce soit fun.", "next": "n2"}]}, "n2": {"speaker": "organizer", "text": "Here''s your first clue: ''I guard the entrance to knowledge, made of stone, in Rome I stand.''", "text_fr": "Voici votre premier indice : ''Je garde l''entrée du savoir, fait de pierre, à Rome je me tiens.''", "choices": [{"text": "That sounds like it''s describing a Roman column or statue.", "text_fr": "Ça ressemble à la description d''une colonne ou statue romaine.", "next": "n3"}, {"text": "Could it be referring to the Roman archway exhibit?", "text_fr": "Ça pourrait faire référence à l''exposition de l''arche romaine ?", "next": "n3"}]}, "n2b": {"speaker": "organizer", "text": "Friendly competition, that''s all! Both teams solving clues at their own pace.", "text_fr": "Une compétition amicale, c''est tout ! Les deux équipes résolvent les indices à leur rythme.", "choices": [{"text": "Sounds fun, let''s see the first clue then!", "text_fr": "Ça a l''air fun, voyons le premier indice alors !", "next": "n2"}]}, "n3": {"speaker": "you_thought", "text": "(You find the Roman archway and discover a hidden clue tucked beside it.)", "text_fr": "(Vous trouvez l''arche romaine et découvrez un indice caché à côté.)", "choices": [{"text": "(Read the next clue aloud.)", "text_fr": "(Lis le prochain indice à voix haute.)", "next": "n4"}]}, "n4": {"speaker": "clue_card", "text": "''Where warriors once fought for glory, find me among ancient armor.''", "text_fr": "''Où les guerriers combattaient jadis pour la gloire, trouvez-moi parmi l''armure ancienne.''", "choices": [{"text": "That must be the gladiator exhibit in the next wing.", "text_fr": "Ça doit être l''exposition des gladiateurs dans l''aile suivante.", "next": "n5"}]}, "n5": {"speaker": "you_thought", "text": "(Rushing to the gladiator exhibit, you spot the rival team already there, searching.)", "text_fr": "(Vous vous précipitez vers l''exposition des gladiateurs, vous repérez l''équipe rivale déjà là, en train de chercher.)", "choices": [{"text": "(Search quickly but carefully, trying to find the clue first.)", "text_fr": "(Cherche vite mais avec soin, en essayant de trouver l''indice en premier.)", "next": "n6"}, {"text": "Good luck finding it! (Search calmly, not rushing despite the competition.)", "text_fr": "Bonne chance pour le trouver ! (Cherche calmement, sans te précipiter malgré la compétition.)", "next": "n6b"}]}, "n6": {"speaker": "you_thought", "text": "(You spot the clue tucked behind a shield display, just moments before the rival team.)", "text_fr": "(Vous repérez l''indice caché derrière une exposition de bouclier, juste avant l''équipe rivale.)", "choices": [{"text": "Got it! Let''s keep moving quickly.", "text_fr": "Trouvé ! Continuons rapidement.", "next": "n7"}]}, "n6b": {"speaker": "rival_team", "text": "(Notices your calm approach) Ha, respect for staying chill about this!", "text_fr": "(Remarque ton approche calme) Ha, respect pour rester détendu là-dessus !", "choices": [{"text": "(Find the clue together, sharing a friendly moment despite the competition.)", "text_fr": "(Trouve l''indice ensemble, partageant un moment amical malgré la compétition.)", "next": "n7"}]}, "n7": {"speaker": "clue_card", "text": "''I hold stories of pharaohs, wrapped tight, kept for eternity.''", "text_fr": "''Je détiens les histoires des pharaons, enveloppées serré, gardées pour l''éternité.''", "choices": [{"text": "That''s clearly pointing to the Egyptian mummy exhibit!", "text_fr": "Ça pointe clairement vers l''exposition de momie égyptienne !", "next": "n8"}]}, "n8": {"speaker": "you_thought", "text": "(At the Egyptian exhibit, you find a small locked box requiring a combination.)", "text_fr": "(À l''exposition égyptienne, vous trouvez une petite boîte verrouillée nécessitant une combinaison.)", "choices": [{"text": "(Look for hints nearby about the combination.)", "text_fr": "(Cherche des indices à proximité pour la combinaison.)", "next": "n9"}]}, "n9": {"speaker": "you_thought", "text": "(A nearby plaque reveals the pharaoh''s reign dates — the likely combination code.)", "text_fr": "(Une plaque à proximité révèle les dates de règne du pharaon — le code de combinaison probable.)", "choices": [{"text": "(Enter the dates as the combination.)", "text_fr": "(Entre les dates comme combinaison.)", "next": "n10"}]}, "n10": {"speaker": "you_thought", "text": "(The box clicks open, revealing the final clue leading to the treasure room.)", "text_fr": "(La boîte s''ouvre avec un clic, révélant l''indice final menant à la salle du trésor.)", "choices": [{"text": "(Race toward the treasure room with excitement.)", "text_fr": "(Cours vers la salle du trésor avec excitation.)", "next": "n11"}]}, "n11": {"speaker": "organizer", "text": "(Waiting at the finish) Congratulations, you''ve completed the hunt! And just ahead of the other team too.", "text_fr": "(Attendant à l''arrivée) Félicitations, vous avez terminé la chasse ! Et juste devant l''autre équipe en plus.", "choices": [{"text": "That was such a fun challenge, thank you for organizing this!", "text_fr": "C''était un défi tellement amusant, merci d''avoir organisé ça !", "next": "n12"}]}, "n12": {"speaker": "rival_team", "text": "(Arriving shortly after, laughing) Well played! That was honestly really fun, win or not.", "text_fr": "(Arrivant peu après, en riant) Bien joué ! C''était honnêtement vraiment fun, gagné ou pas.", "choices": [{"text": "It really was — great competing with you both!", "text_fr": "C''était vraiment le cas — super de rivaliser avec vous !", "next": "end_hunt"}]}, "end_hunt": {"speaker": "organizer", "text": "This is exactly the spirit we hoped for — friendly competition and cultural discovery combined!", "text_fr": "C''est exactement l''esprit qu''on espérait — compétition amicale et découverte culturelle combinées !", "end": true, "ending_label": "Chasse au trésor culturelle remportée avec brio 🗺️🏆"}}}'::jsonb, is_playable = true
where title = 'Une chasse au trésor culturelle dans le musée'
  and theme_id = (select id from scenario_themes where position = 12 and language_id = (select id from languages where code = 'en'));
